local gui = LMG2L["ScreenGui_1"]
local frame = LMG2L["Frame_2"]

local TweenService = game:GetService("TweenService")
local toggleButton = LMG2L["TextButton_a"]

frame.AnchorPoint = Vector2.new(1, 0)
frame.Position = UDim2.new(1, 0, 0, 30)

local aberta = false
local larguraBarra = 4

local function getPosicaoFechada()
	local larguraReal = frame.AbsoluteSize.X
	local parteVisivel = larguraBarra

	local offset = larguraReal - parteVisivel

	return UDim2.new(1, offset, 0, 30)
end

frame.Position = getPosicaoFechada()

toggleButton.MouseButton1Click:Connect(function()

	local destino

	if aberta then
		destino = getPosicaoFechada()
	else
		destino = UDim2.new(1, 0, 0, 30)
	end

	local tween = TweenService:Create(
		frame,
		TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		{Position = destino}
	)

	tween:Play()
	aberta = not aberta
end)
local musicBox = LMG2L["TextBox_4"]
local pitchBox = LMG2L["lol_5"]
local distBox = LMG2L["TextBox_6"]
local playButton = LMG2L["TextButton_7"]


local player = game.Players.LocalPlayer  
local character = player.Character or player.CharacterAdded:Wait()  
local root = character:WaitForChild("HumanoidRootPart")  
local runService = game:GetService("RunService")  


local quantidade = 40  
local raioBase = 7  
local alturaBase = 0.1  


local sound = Instance.new("Sound")  
sound.Parent = root  
sound.Volume = 1  
sound.Looped = true  

local distortion = Instance.new("DistortionSoundEffect")
distortion.Parent = sound


local blocos = {}  

for i = 1, quantidade do  
	local bloco = Instance.new("Part")  
	bloco.Size = Vector3.new(0.25, alturaBase, 0.25)  
	bloco.Anchored = true  
	bloco.CanCollide = false  
	bloco.Material = Enum.Material.Neon  
	bloco.TopSurface = Enum.SurfaceType.Smooth  
	bloco.BottomSurface = Enum.SurfaceType.Smooth  
	bloco.Color = Color3.fromRGB(255,255,255)  
	bloco.Parent = workspace  

	table.insert(blocos, bloco)  
end  

playButton.MouseButton1Click:Connect(function()

	if musicBox.Text ~= "" then  
		sound.SoundId = "rbxassetid://" .. musicBox.Text  
	end  

	sound.PlaybackSpeed = tonumber(pitchBox.Text) or 1  
	distortion.Level = tonumber(distBox.Text) or 0  

	sound:Play()  
end)

local MAX_ALTURA = 6
local MIN_ALTURA = 0.1  
local SUAVIZACAO = 0.25  
local ESCALA_LOUDNESS = 0.0027  
local ESCALA_RAIO = 0.03  

local rotacao = 0
local velocidadeRotacao = 0.2

local variacao = {}  
local alturaAtual = {}  
local boostAleatorio = {}  
local raioAtual = {}  

for i = 1, quantidade do  
	variacao[i] = math.random(80,120) / 100  
	alturaAtual[i] = MIN_ALTURA  
	raioAtual[i] = raioBase  

	if math.random(1,4) == 1 then  
		boostAleatorio[i] = math.random(130,190) / 100  
	else  
		boostAleatorio[i] = math.random(70,110) / 100  
	end  
end  

runService.RenderStepped:Connect(function(deltaTime)  

	rotacao = rotacao + velocidadeRotacao * deltaTime  

	local loudness = sound.PlaybackLoudness * ESCALA_LOUDNESS  

	for i, bloco in ipairs(blocos) do  

		local angulo = (2 * math.pi / quantidade) * i + rotacao  

		local tipoBeat  
		if i % 3 == 0 then  
			tipoBeat = loudness * 1.2  
		elseif i % 3 == 1 then  
			tipoBeat = loudness * 0.9  
		else  
			tipoBeat = loudness * 0.6  
		end  

		local alvoAltura = MIN_ALTURA +  
			(tipoBeat * variacao[i] * boostAleatorio[i])  

		alvoAltura = math.clamp(alvoAltura, MIN_ALTURA, MAX_ALTURA)  

		alturaAtual[i] = alturaAtual[i] +  
			(alvoAltura - alturaAtual[i]) * SUAVIZACAO  

		local alvoRaio = raioBase +  
			(tipoBeat * 20 * ESCALA_RAIO)  

		raioAtual[i] = raioAtual[i] +  
			(alvoRaio - raioAtual[i]) * SUAVIZACAO  

		local posX = root.Position.X + math.cos(angulo) * raioAtual[i]  
		local posZ = root.Position.Z + math.sin(angulo) * raioAtual[i]  

		bloco.Size = Vector3.new(0.25, alturaAtual[i], 0.25)  
		bloco.Position = Vector3.new(posX, root.Position.Y, posZ)  

		if sound.IsPlaying then
			local hue = (i/quantidade + tick()*0.1) % 1
			local saturacao = 0.25 + math.clamp(loudness * 0.5, 0, 0.2)
			bloco.Color = Color3.fromHSV(hue, saturacao, 1)
		else
			bloco.Color = Color3.fromRGB(255,255,255)
		end
	end  
end)

return LMG2L["ScreenGui_1"], require;
